import requests
from bs4 import BeautifulSoup
from openai import OpenAI
from pydub import AudioSegment
import io

# Initialize OpenAI client
client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

urls = [
    "https://paulgraham.com/ds.html",
    "https://paulgraham.com/foundermode.html"
]
output_file = "/root/audiobook.mp3"

def fetch_text(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        soup = BeautifulSoup(response.content, 'html.parser')

        # Paul Graham's essays are typically inside <font face="verdana">
        # We find all such tags and pick the one with the most text to avoid navigation menus
        fonts = soup.find_all('font', {'face': 'verdana'})
        if fonts:
            # Filter out very short texts which might be menu items
            candidates = [f for f in fonts if len(f.get_text()) > 500]
            if candidates:
